	ngOnInit(): void {
		const canonical = this.document.querySelector('link[rel="canonical"]') as HTMLAnchorElement | null;
		if (canonical) canonical.href = 'https://bigaunt666.github.io/bigaunt/teamsForm';
		of(this.layoutService.setPageLoading(true))
			.pipe(
				switchMap(() => this.getTeamsList()),
				switchMap(() => this.getSession$()),
				tap((res) => this.setNBALogoMap()),
				tap((sessionRes) => this.setUserData(sessionRes)),
				switchMap((sessionRes) => {
					// 判斷是否有登入
					if (!sessionRes.session) return of(null);
					else return this.getDiscountCode$(JSON.parse(localStorage.getItem('profile')).id)
				}),
				tap((discountCodeRes) => {
					// 如有登入才去往下執行(沒有折扣碼也會執行，但不影響前端顯示 - 即為空下拉選單，不會壞掉)
					if (!!discountCodeRes) {
						this.isDiscountCode = true;
						this.discountCodeOptions = discountCodeRes.map((item) => {
							return {
								label: item.discountCode + ' - $' + item.discountAmount,
								value: item.discountCode
							}
						})
					}
				}),
				finalize(() => this.layoutService.setPageLoading(false))
			)
			.subscribe();
	}

