	// 帶入會員資料
	setUserData(sessionRes) {
		if (!sessionRes.session) return;
		let profile = JSON.parse(localStorage.getItem('profile'));
		const userData = {
			buyerName: profile.name,
			buyerNickName: profile.nickName,
			buyerEmail: profile.email,
			buyerPhone: profile.phone,
			buyerBankAccount: profile.bankAccount,
			'711Name': profile['711Name']
		};
		this.buyerForm.patchValue(userData);
	}

