	getTeamsList(): Observable<any> {
		return from(this.supabaseService.getTeams(this.tableName)).pipe(
			tap(({ data }) => {
				this.teamsList = data;
			})
		);
	}

	openDetailPage() {
		// 重置被選中隊伍
		this.selectedTeamsList = [];
		// 重置折扣金額為0
		this.buyerForm.controls.discountAmount.setValue(0);

		// 檢查必填欄位及格式
		if (this.buyerForm.invalid) {
			this.messageService.add({
				severity: 'error',
				summary: `注意`,
				detail: '尚有必填欄位未填寫或是格式不對',
				icon: 'bounce animated',
				life: 5000,
			});
			return;
		}
		let selectedTeamsIdArr = [];
		const selectedTeamsList = this.teamsList.filter((item) => {
			// 將被選取的隊伍整理成id陣列，送去checkThisTeamIsLock做檢查
			if (!!item.isSelected) selectedTeamsIdArr.push(item.id)
			return !!item.isSelected
		});
		this.selectedTeamsList = selectedTeamsList;
		if (selectedTeamsIdArr.length <= 0) {
			this.messageService.add({
				severity: 'error',
				summary: `注意`,
				detail: '尚未選擇任何隊伍',
				icon: 'bounce animated',
				life: 5000,
			});
			return;
		}
		if (this.buyerForm.value.addDisplayCard < 0) {
			this.messageService.add({
				severity: 'error',
				summary: `注意`,
				detail: '球卡支架數量不得為負數',
				icon: 'bounce animated',
				life: 5000,
			});
			return;
		}
		if (!!this.buyerForm.value.discountCode) {
			// let discountInfo = await this.checkDiscountCode(this.buyerForm.value.discountCode);
			// if (discountInfo.length <= 0) {
			// 	this.messageService.add({
			// 		severity: 'error',
			// 		summary: `注意`,
			// 		detail: '折扣代碼不存在',
			// 		icon: 'bounce animated',
			// 		life: 5000,
			// 	});
			// 	return;
			// } else {
			// 	this.buyerForm.controls.discountAmount.setValue(discountInfo[0].discountAmount);
			// }
			of(null)
				.pipe(
					tap(() => this.layoutService.setPageLoading(true)),
					switchMap(() => this.checkDiscountCode$(this.buyerForm.value.discountCode)),
					switchMap((discountInfo) => {
						if (discountInfo.length <= 0) {
							this.messageService.add({
								severity: 'error',
								summary: `注意`,
								detail: '折扣代碼不存在',
								icon: 'bounce animated',
								life: 5000,
							});
							return EMPTY;
						} else {
							this.buyerForm.controls.discountAmount.setValue(discountInfo[0].discountAmount);
							return of(true);
						}
					}),
					finalize(() => this.layoutService.setPageLoading(false))
				)
				.subscribe(() => {
					this.mode = 'detail';
				});
		} else this.mode = 'detail';
	}

	// 計算所有隊伍費用總額
	calcTotalTeamsCost(teams) {
		let total = teams.reduce((total, item) => {
			const numericPrice = item.priceNum;
			return total + (isNaN(numericPrice) ? 0 : numericPrice); // 保險起見，排除非數字
		}, 0);
		total = !!this.buyerForm.value.addDisplayCard ? total + this.buyerForm.value.addDisplayCard * 10 : total;
		let discountAmount = this.buyerForm.value.discountAmount;
		// if (!!discountAmount) return total - discountAmount;
		// else return total;
		let result;
		if (!!discountAmount) {
			if (teams.length >= 2) result = Math.round(total * 0.9) - discountAmount;
			else result = total - discountAmount;
		} else {
			if (teams.length >= 2) result = Math.round(total * 0.9);
			else result = total;
		}
		result = result <= 0 ? 0 : result;
		return result;
	}

	generateUUIDv4() {
		return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
			const r = Math.random() * 16 | 0;
			const v = c === 'x' ? r : (r & 0x3 | 0x8);
			return v.toString(16);
		});
	}

