	// 				console.log('完成表單資料：', this.buyerForm.value);
	// 			},
	// 			error: (err) => {
	// 				if (err.message !== 'TEAM_LOCKED') console.error(err);
	// 			}
	// 		});
	// }

	confirmOrderDetail() {
		of(null)
			.pipe(
				tap(() => this.layoutService.setPageLoading(true)),
				// 1. 設定基本欄位
				tap(() => {
					this.buyerForm.patchValue({
						submitTaiwanTime: moment().format('YYYY-MM-DD HH:mm:ss'),
						isLock: true,
						groupIdForSentEmail: this.generateUUIDv4(),
					});
				}),
				// 2. 取得選中的隊伍 id
				map(() =>
					this.teamsList
						.filter(
							t => t.isSelected
						)
						.map(t => t.id)
				),
				// 3. 直接搶隊（取代 check + update）
				switchMap(
					selectedTeamsIdArr =>
						this.lockTeams$(selectedTeamsIdArr).pipe(
							map(success => ({ success, selectedTeamsIdArr}))
						)
				),

				// 4. 搶失敗
				tap(({ success }) => {
					if (!success) {
						this.messageService.add(
							{
								severity: 'error',
								summary: '注意',
								detail: '您選中的隊伍已被別人搶先一步，請重新整理頁面後再選取',
								icon: 'bounce animated',
								life: 5000,
							}
						);
						throw new Error( 'TEAM_LOCKED');
					}
				}),
				// 5. 更新折扣碼
				switchMap(() => {
					return this
						.buyerForm.value
						.discountCode !==
						'GUTURTLE100'
						? this.updateDiscountCodeToIsUsed$(
								this
									.buyerForm
									.value
									.discountCode
						)
						: of(null);
				}),
				finalize(() => this.layoutService.setPageLoading(false))
			)
			.subscribe({
				next: () => {
					console.log('完成表單資料：', this.buyerForm.getRawValue());
					// TODO:
					// 成功後寄信
					// 跳付款
					// 顯示成功 dialog
				},
				error: err => {
					if (err.message !== 'TEAM_LOCKED') {
						console.error(err);
						this.messageService.add(
							{
								severity: 'error',
								summary: '系統錯誤',
								detail: '訂單建立失敗，請稍後再試',
								life: 5000,
							}
						);
					}
				},
			});
	}

	// - 確認是否有任一隊伍是否已被其他人選取
	checkAnyTeamsIsLock$(selectedTeamsIdArr: string[]): Observable<boolean> {
		return from(this.supabaseService.getTeamsById(selectedTeamsIdArr, this.tableName)).pipe(
			map(({ data }) => {
				if (!data) return false;
				return data.some(item => !!item.isLock);
			})
		);
	}


	// - 送出表單
	updateTeamInfo$(selectedTeamsIdArr: string[]) {
		return from(
			this.supabaseService.updateTeamInfo(
				selectedTeamsIdArr,
				this.buyerForm.value,
				this.tableName
			)
		).pipe(
			tap(({ data }) => {
				if (!!data) {
					this.messageService.add({
						severity: 'success',
						summary: `成功`,
						detail: '訂購成功',
						icon: 'bounce animated',
						life: 5000,
					});
					this.mode = 'success';
			}
			}),
			catchError(err => {
				console.error('Unexpected error:', err);
				this.messageService.add({
					severity: 'error',
					summary: `錯誤`,
					detail: '請聯絡大阿姨團隊',
					icon: 'bounce animated',
					life: 5000,
				});
				return of(null); // Observable 必須回傳可訂閱的東西
			})
		);
	}

	// - 檢查折扣代碼是否存在
	checkDiscountCode$(discountCode): Observable<any> {
		return from(this.supabaseService.checkDiscountCode(discountCode)).pipe(
			map(({ data }) => data),
			catchError((err) => {
				console.error('Unexpected error:', err);
				return of(false); // 回傳 false 代表錯誤
			})
		);
	}

	// - 將使用過折扣代碼isUsed更新為true
	updateDiscountCodeToIsUsed$(discountCode: string): Observable<any> {
		return from(this.supabaseService.updateDiscountCodeToIsUsed(discountCode)).pipe(
			map(({ data, error }) => {
				if (error) throw error;
				return data;
			}),
			catchError((err) => {
				console.error('Unexpected error:', err);
				return of(false); // 回傳 false 表示失敗
			})
		);
	}

	// - 取得登入狀態
	getSession$(): Observable<any> {
		return from(this.supabaseService.getSession()).pipe(
			map(({ data, error }) => {
				if (error) throw error;
				return data;
			})
		);
	}

	// - 取得個人折扣代碼
	getDiscountCode$(personId: any): Observable<any> {
		return from(this.supabaseService.getDiscountCode(personId)).pipe(
			map(({ data, error }) => {
				if (error) throw error;
				return data;
			})
		);
	}

	// - 搶隊伍 + 寫入購買資料
lockTeams$(selectedTeamIds: number[]): Observable<boolean> {
	return from(
		this.supabaseService.lockTeams(
			this.tableName,
			selectedTeamIds,
			this.buyerForm.getRawValue()
		)
	).pipe(
		map(({ data, error }) => {
			if (error) throw error;
			return data as boolean;
		}),

		tap(success => {
			if (success) {
				this.messageService.add({
					severity: 'success',
					summary: '成功',
					detail: '訂購成功',
					icon: 'bounce animated',
					life: 5000,
				});

				this.mode = 'success';
			}
		}),

		catchError(err => {
			console.error('Unexpected error:', err);

			this.messageService.add({
				severity: 'error',
				summary: '錯誤',
				detail: '請聯絡大阿姨團隊',
				icon: 'bounce animated',
				life: 5000,
			});

			return of(false); // 保持 Observable 流不中斷
		})
	);
}
